 sacrif:({id})=>{const p=S.pni.find(x=>x.id===id);if(!p)return;p.sacrif=!p.sacrif;toast(p.sacrif?tr('<b>{net} PNI is now a sacrificial choke point.</b><br>A flood from there dies on the small port instead of inside your network, but legit traffic over it runs at half capacity.',{net:NET[p.net].name}):tr('<b>{net} PNI is back to normal.</b>',{net:NET[p.net].name}),p.sacrif?'good':'');after();},
 ixbh:()=>{const a=S.ev.ddos;if(!a){toast(tr('<b>No attack to blackhole right now.</b>'),'');return;}if(!hasIxAt(a.city)){toast(tr('<b>No IX in {city} to announce a blackhole to.</b>',{city:CITY[a.city].name}),'bad');sfx('err');return;}a.ixbh=!a.ixbh;toast(a.ixbh?tr('<b>IX blackhole announced in {city}.</b><br>About half the members honour the /32 and drop the junk. The customer stays up.',{city:CITY[a.city].name}):tr('<b>IX blackhole withdrawn.</b>'),a.ixbh?'good':'');sfx('alert');after();},
